INSERT INTO ip_adjust_log (
    security_code
    ,security_short_name
    ,security_type
    ,crmw_name
    ,crmw_scode
    ,crmw_mktcode
    ,crmw_stype
    ,adjust_type
    ,adjust_mode
    ,adjust_batch_no
    ,target_pool_id
    ,target_pool_name
    ,pool_type
    ,audit_status
    ,adjuster_id
    ,adjuster_name
    ,adjust_reason
    ,adjust_advice
    ,submit_time
    ,audit_time
    ,entry_time
    ,is_deleted
    ,crte_time
    ,updt_time
) VALUES (
    #{securityCode}
    ,#{securityShortName}
    ,#{securityType}
    ,#{crmwName}
    ,#{crmwScode}
    ,#{crmwMktcode}
    ,#{crmwStype}
    ,#{adjustType}
    ,#{adjustMode}
    ,#{adjustBatchNo}
    ,#{targetPoolId}
    ,#{targetPoolName}
    ,#{poolType}
    ,#{auditStatus}
    ,#{adjusterId}
    ,#{adjusterName}
    ,#{adjustReason}
    ,#{adjustAdvice}
    ,COALESCE(#{submitTime}, NOW())
    ,#{auditTime}
    ,#{entryTime}
    ,0
    ,NOW()
    ,NOW()
)

