FROM ip_pool_status_crmw
WHERE is_deleted = 0
  AND security_code = #{securityCode}
  AND crmw_scode <=> #{crmwScode}
  AND crmw_stype <=> #{crmwStype}
  AND target_pool_id = #{targetPoolId}
  AND audit_status = '20'
FOR UPDATE

mapper.update:
UPDATE ip_pool_status_crmw
SET is_deleted = 1
   ,updt_time = #{updateTime}
WHERE id = #{id}
  AND is_deleted = 0
  AND audit_status = '20'

UPDATE ip_pool_status_crmw source_row LEFT JOIN ip_pool_status_crmw formal_row ON formal_row.security_code <=> source_row.security_code AND formal_row.crmw_scode = #{bo.securityCode} AND formal_row.crmw_stype = #{bo.securityType} AND formal_row.target_pool_id <=> source_row.target_pool_id AND formal_row.audit_status = '20' AND formal_row.is_deleted = 0 AND formal_row.id != source_row.id LEFT JOIN ip_pool_status_crmw earlier_row ON earlier_row.security_code <=> source_row.security_code AND earlier_row.crmw_scode = #{bo.tempSecurityCode} AND earlier_row.target_pool_id <=> source_row.target_pool_id AND earlier_row.audit_status = '20' AND earlier_row.is_deleted = 0 AND earlier_row.id < source_row.id SET source_row.crmw_name = CASE WHEN formal_row.id IS NULL AND earlier_row.id IS NULL THEN #{bo.shortName} ELSE source_row.crmw_name END ,source_row.crmw_scode = CASE WHEN formal_row.id IS NULL AND earlier_row.id IS NULL THEN #{bo.securityCode} ELSE source_row.crmw_scode END ,source_row.crmw_mktcode = CASE WHEN formal_row.id IS NULL AND earlier_row.id IS NULL THEN #{bo.securityMarket} ELSE source_row.crmw_mktcode END ,source_row.crmw_stype = CASE WHEN formal_row.id IS NULL AND earlier_row.id IS NULL THEN #{bo.securityType} ELSE source_row.crmw_stype END ,source_row.is_deleted = CASE WHEN formal_row.id IS NOT NULL OR earlier_row.id IS NOT NULL THEN 1 ELSE source_row.is_deleted END ,source_row.updt_time = #{bo.updateTime} WHERE source_row.id IN
#{item}
AND source_row.is_deleted = 0 AND source_row.crmw_scode = #{bo.tempSecurityCode} AND source_row.audit_status = '20'

